import { randomBytes } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import type { Readable } from 'node:stream';
import { HttpError } from '../lib/errors.js';

/**
 * Uploaded files live in one folder on disk under random names; the database
 * keeps the original name and type. Files are never served from this folder
 * directly, only through the API, which checks access first.
 */

export function attachmentPath(dir: string, storedName: string): string {
  // Stored names are generated by us, but never trust a name to stay inside the folder.
  if (!/^[A-Za-z0-9_-]{16,64}$/.test(storedName)) throw new Error('Invalid stored file name.');
  return path.join(dir, storedName);
}

export function newStoredName(): string {
  return randomBytes(18).toString('base64url');
}

/**
 * Streams a request body into a new file, stopping as soon as it grows past
 * `maxBytes`. Resolves with the number of bytes written.
 */
export function saveStream(source: Readable, file: string, maxBytes: number): Promise<number> {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  return new Promise((resolve, reject) => {
    const out = fs.createWriteStream(file, { flags: 'wx', mode: 0o600 });
    let size = 0;
    let failed = false;
    const fail = (error: Error) => {
      if (failed) return;
      failed = true;
      source.unpipe(out);
      source.resume();
      out.destroy();
      fs.rm(file, { force: true }, () => reject(error));
    };
    source.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > maxBytes) {
        fail(new HttpError(413, `Files can be at most ${formatBytes(maxBytes)}.`));
      }
    });
    source.on('error', (error) => fail(error));
    source.on('aborted', () => fail(new HttpError(400, 'The upload was interrupted.')));
    out.on('error', (error) => fail(error));
    out.on('finish', () => {
      if (!failed) resolve(size);
    });
    source.pipe(out);
  });
}

export function removeFile(file: string): void {
  try {
    fs.rmSync(file, { force: true });
  } catch (error) {
    console.error(`Couldn't remove ${file}: ${error instanceof Error ? error.message : String(error)}`);
  }
}

export function removeAttachmentFiles(dir: string, storedNames: string[]): void {
  for (const name of storedNames) {
    try {
      removeFile(attachmentPath(dir, name));
    } catch {
      // Ignore names that don't look like ours.
    }
  }
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} bytes`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${Math.round((bytes / 1024 / 1024) * 10) / 10} MB`;
  return `${Math.round((bytes / 1024 / 1024 / 1024) * 10) / 10} GB`;
}

/** Makes an uploaded file name safe to store and to send back in a header. */
export function cleanFilename(raw: string): string {
  const base = raw.split(/[\\/]/).pop() ?? '';
  // eslint-disable-next-line no-control-regex
  const cleaned = base.replace(/[\u0000-\u001f\u007f]/g, '').replace(/\s+/g, ' ').trim();
  const limited = cleaned.length > 200 ? cleaned.slice(0, 200) : cleaned;
  return limited || 'file';
}

/** A short list of types worth recognising; everything else is a download. */
const TYPES: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  gif: 'image/gif',
  webp: 'image/webp',
  svg: 'image/svg+xml',
  pdf: 'application/pdf',
  txt: 'text/plain',
  csv: 'text/csv',
  md: 'text/markdown',
  json: 'application/json',
  zip: 'application/zip',
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  ppt: 'application/vnd.ms-powerpoint',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  mp4: 'video/mp4',
  mov: 'video/quicktime',
  mp3: 'audio/mpeg',
};

/** The type of a file, decided by its extension (browsers' claims aren't trusted). */
export function mimeTypeFor(filename: string): string {
  const ext = filename.toLowerCase().split('.').pop() ?? '';
  return TYPES[ext] ?? 'application/octet-stream';
}

/** Checks the first bytes of an image so a renamed file can't pose as one. */
export function looksLikeImage(file: string, mimeType: string): boolean {
  let header: Buffer;
  try {
    const fd = fs.openSync(file, 'r');
    header = Buffer.alloc(12);
    fs.readSync(fd, header, 0, 12, 0);
    fs.closeSync(fd);
  } catch {
    return false;
  }
  switch (mimeType) {
    case 'image/png':
      return header.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
    case 'image/jpeg':
      return header[0] === 0xff && header[1] === 0xd8 && header[2] === 0xff;
    case 'image/gif':
      return header.subarray(0, 4).toString('latin1') === 'GIF8';
    case 'image/webp':
      return header.subarray(0, 4).toString('latin1') === 'RIFF' && header.subarray(8, 12).toString('latin1') === 'WEBP';
    default:
      return false;
  }
}
